package countingsort

import (
	"reflect"
	"testing"
)

func TestEmpty(t *testing.T) {
	result := CountingSort([]int{})
	if len(result) != 0 {
		t.Errorf("CountingSort([]) = %v, want []", result)
	}
}

func TestSingle(t *testing.T) {
	result := CountingSort([]int{5})
	if !reflect.DeepEqual(result, []int{5}) {
		t.Errorf("CountingSort([5]) = %v, want [5]", result)
	}
}

func TestReversed(t *testing.T) {
	result := CountingSort([]int{5, 4, 3, 2, 1})
	want := []int{1, 2, 3, 4, 5}
	if !reflect.DeepEqual(result, want) {
		t.Errorf("CountingSort([5..1]) = %v, want %v", result, want)
	}
}

func TestDuplicates(t *testing.T) {
	result := CountingSort([]int{3, 1, 4, 1, 5, 9, 2, 6, 5, 3})
	want := []int{1, 1, 2, 3, 3, 4, 5, 5, 6, 9}
	if !reflect.DeepEqual(result, want) {
		t.Errorf("CountingSort(pi digits) = %v, want %v", result, want)
	}
}
